document.getElementById('year').textContent = new Date().getFullYear();const header = document.getElementById('siteHeader');const onScroll =()=> header.classList.toggle('scrolled',window.scrollY > 20);onScroll();window.addEventListener('scroll',onScroll,{passive:true});const servicesSection = document.getElementById('uslugi');if(servicesSection){const bgObserver = new IntersectionObserver((entries,obs)=>{entries.forEach(entry =>{if(!entry.isIntersecting)return;const script = document.createElement('script');script.type = 'module';script.src = 'js/services-bg.js';document.body.appendChild(script);obs.disconnect()})},{rootMargin:'400px'});bgObserver.observe(servicesSection)}const lazyVideos = document.querySelectorAll('video.lazy-video');const videoObserver = new IntersectionObserver((entries,obs)=>{entries.forEach(entry =>{if(!entry.isIntersecting)return;const video = entry.target;video.querySelectorAll('source[data-src]').forEach(source =>{source.src = source.dataset.src;source.removeAttribute('data-src')});video.load();video.play().catch(()=>{});obs.unobserve(video)})},{rootMargin:'200px'});lazyVideos.forEach(v => videoObserver.observe(v));const videoLightbox = document.getElementById('videoLightbox');const videoLightboxPlayer = document.getElementById('videoLightboxPlayer');const videoLightboxClose = document.getElementById('videoLightboxClose');function openVideoLightbox(src){videoLightboxPlayer.src = src;videoLightbox.hidden = false;document.body.style.overflow = 'hidden';videoLightboxPlayer.play().catch(()=>{})}function closeVideoLightbox(){videoLightbox.hidden = true;document.body.style.overflow = '';videoLightboxPlayer.pause();videoLightboxPlayer.removeAttribute('src');videoLightboxPlayer.load()}document.querySelectorAll('.gallery-tile[data-video-src]').forEach(tile =>{const trigger = tile.querySelector('.gallery-play')|| tile;trigger.addEventListener('click',(e)=>{e.stopPropagation();openVideoLightbox(tile.dataset.videoSrc)})});videoLightboxClose.addEventListener('click',closeVideoLightbox);videoLightbox.addEventListener('click',(e)=>{if(e.target === videoLightbox)closeVideoLightbox()});document.addEventListener('keydown',(e)=>{if(e.key === 'Escape' && !videoLightbox.hidden)closeVideoLightbox()});const burger = document.getElementById('burger');const mainNav = document.getElementById('mainNav');burger.addEventListener('click',()=> mainNav.classList.toggle('open'));mainNav.querySelectorAll('a').forEach(a => a.addEventListener('click',()=> mainNav.classList.remove('open')));const dict ={pl:{'brand.logo':'<strong>Cyfrowa.</strong>Moc','nav.services':'Usługi','nav.about':'O mnie','nav.portfolio':'Portfolio','nav.contact':'Kontakt','nav.cta':'Kontakt','hero.eyebrow':'Digital Marketing · Polska - Niemcy','hero.headline':'Od strategii<br>po realizację.','hero.sub':'Social media,strony WWW,SEO i reklama — wszystko czego potrzebujesz,żeby Twoja firma zaistniała i rosła online.','hero.tagline':'Cyfrowa siła dla Twojego biznesu.','hero.ctaPrimary':'Bezpłatna wycena','hero.ctaSecondary':'Zobacz usługi','hero.badgeDrone':'Licencja dronowa A1/A3 · DJI','hero.badgeBilingual':'Polski · Deutsch · English','hero.badgeAI':'Reklamy wspierane AI','trust.line':'Strategia · Design · Dron · SEO · Social Media — wszystko pod jednym dachem.','services.eyebrow':'Co robimy','services.title':'Usługi,które napędzają Twoją markę','services.sub':'Kompleksowa obsługa digital marketingu — od pierwszego szkicu strategii po gotową kampanię.','services.web.title':'Strony internetowe','services.web.desc':'Nowoczesne,szybkie i responsywne strony WWW,które sprzedają — projektowane pod konwersję i SEO.','services.social.title':'Obsługa social mediów','services.social.desc':'Strategia,treści i community management na Instagram,Facebook,TikTok i LinkedIn — więcej niż lajki:realne zasięgi i klienci.','services.drone.title':'Zdjęcia i filmy z drona','services.drone.desc':'Profesjonalne ujęcia z drona DJI(licencja A1/A3)— nieruchomości,eventy,reklama,wideo produktowe.','services.ai.title':'Reklamy z wykorzystaniem AI','services.ai.desc':'Kreacje reklamowe generowane i wspierane sztuczną inteligencją — szybciej,taniej,skuteczniej.','services.seo.title':'SEO i reklama','services.seo.desc':'Widoczność w Google i płatne kampanie(Google Ads,Meta Ads)— mierzalne,skalowalne i opłacalne od pierwszego kliknięcia.','services.strategy.title':'Strategia i branding','services.strategy.desc':'Marka,którą klienci rozpoznają i pamiętają — od strategii,przez identyfikację wizualną,po konsekwentne wdrożenie.','about.eyebrow':'Kim jestem','about.title':'Polak w Niemczech,marketing cyfrowy to moja pasja i wykształcenie','about.p1':'Od ponad 10 lat mieszkam w Niemczech,łącząc polską wszechstronność z niemiecką precyzją w pracy z klientami. Doświadczenie zawodowe zdobywałem w Wyższej Szkole Menedżerskiej w Warszawie,a swoje kompetencje stale rozwijam na kursach doszkalających — m.in. DCI w Berlinie.','about.p2':'Oprócz strategii marketingowej i budowy stron internetowych,sam realizuję wiele projektów,tj. AI Influenserka,reklamy,zdjęcia i filmy z drona serii DJI — posiadam licencję operatora A1/A3,dzięki czemu Twoje treści wideo powstają w pełni legalnie i profesjonalnie.','about.li1':'Ponad 10 lat doświadczenia życiowego i zawodowego w Niemczech','about.li2':'Wykształcenie:Wyższa Szkoła Menedżerska w Warszawie','about.li3':'Regularne szkolenia branżowe','about.li4':'Licencjonowany operator dronów DJI(A1/A3)','stats.years':'lat doświadczenia w DE','stats.license':'licencja pilota drona','stats.lang':'języki obsługi klienta','stats.service':'marketing od A do Z','portfolio.eyebrow':'Realizacje','portfolio.title':'Z lotu drona i nie tylko','portfolio.sub':'Wybrane materiały. Pełne portfolio i case study — na zapytanie.','portfolio.showreel':'Reklama zrobiona w Digital Power','portfolio.ai':'Wykorzystanie AI','portfolio.aiInfluencer':'camila.nomadfit — nasza AI Influenserka','portfolio.storyboard':'Reklama firmy budowlanej','process.eyebrow':'Jak pracujemy','process.title':'Od strategii po realizację — krok po kroku','process.s1.title':'Analiza i strategia','process.s1.desc':'Poznajemy Twój biznes,cele i konkurencję — żeby żadne działanie nie było przypadkowe.','process.s2.title':'Projekt i produkcja','process.s2.desc':'Tworzymy stronę,treści,zdjęcia i filmy z drona oraz kreacje wspierane AI — dopasowane do Twojej marki.','process.s3.title':'Wdrożenie','process.s3.desc':'Publikujemy i konfigurujemy kampanie oraz social media zgodnie z ustalonym planem — bez niespodzianek.','process.s4.title':'Wzrost i optymalizacja','process.s4.desc':'Analizujemy wyniki i stale poprawiamy skuteczność Twojego marketingu online — dobry wynik to dopiero początek.','process.trust':'Działamy w zgodzie z RODO i standardami bezpieczeństwa danych — Twoje dane wykorzystujemy wyłącznie do realizacji zapytania i nie przekazujemy ich stronom trzecim do celów marketingowych. Szczegóły w <a href="polityka-prywatnosci.html">Polityce Prywatności</a>.','ctaBanner.title':'Gotowy,by Twoja firma zaistniała online?','ctaBanner.sub':'Napisz do mnie — omówimy bezpłatnie zakres i wycenę projektu.','ctaBanner.btn':'Skontaktuj się','contact.eyebrow':'Kontakt','contact.title':'Porozmawiajmy o Twoim projekcie','contact.sub':'Odpowiadam po polsku,niemiecku i angielsku. Napisz e-mail lub wypełnij formularz obok.','contact.location':'Goslarstraße 5,44359 Dortmund','contact.languages':'Polski · Deutsch · English','contact.form.name':'Imię i nazwisko','contact.form.email':'Adres e-mail','contact.form.subject':'Czego dotyczy zapytanie?','contact.form.opt1':'Strona internetowa','contact.form.opt2':'Social media','contact.form.opt3':'Zdjęcia / film z drona','contact.form.opt4':'Reklama i SEO','contact.form.opt5':'Inne','contact.form.message':'Wiadomość','contact.form.send':'Wyślij zapytanie','footer.tagline':'Cyfrowa siła dla Twojego biznesu.','footer.legal':'<a href="polityka-prywatnosci.html">Polityka Prywatności</a> · <a href="impressum.html">Impressum</a>',},de:{'brand.logo':'<strong>Digital.</strong>Power','nav.services':'Leistungen','nav.about':'Über mich','nav.portfolio':'Portfolio','nav.contact':'Kontakt','nav.cta':'Kontakt','hero.eyebrow':'Digitalmarketing · Polen - Deutschland','hero.headline':'Von der Strategie<br>bis zur Umsetzung.','hero.sub':'Social Media,Websites,SEO und Werbung — alles,was Ihr Unternehmen braucht,um online sichtbar zu werden und zu wachsen.','hero.tagline':'Digitale Kraft für Ihr Unternehmen.','hero.ctaPrimary':'Kostenloses Angebot','hero.ctaSecondary':'Leistungen ansehen','hero.badgeDrone':'Drohnenlizenz A1/A3 · DJI','hero.badgeBilingual':'Polnisch · Deutsch · Englisch','hero.badgeAI':'KI-gestützte Werbung','trust.line':'Strategie · Design · Drohne · SEO · Social Media — alles aus einer Hand.','services.eyebrow':'Was wir tun','services.title':'Leistungen,die Ihre Marke voranbringen','services.sub':'Digitalmarketing aus einer Hand — vom ersten Strategieentwurf bis zur fertigen Kampagne.','services.web.title':'Websites','services.web.desc':'Moderne,schnelle und responsive Websites,die verkaufen — konzipiert für Conversion und SEO.','services.social.title':'Social-Media-Betreuung','services.social.desc':'Strategie,Content und Community-Management für Instagram,Facebook,TikTok und LinkedIn — mehr als Likes:echte Reichweite und Kunden.','services.drone.title':'Drohnenfotos und -videos','services.drone.desc':'Professionelle DJI-Drohnenaufnahmen(Lizenz A1/A3)— Immobilien,Events,Werbung,Produktvideos.','services.ai.title':'KI-gestützte Werbung','services.ai.desc':'Werbekreationen,erstellt und unterstützt durch künstliche Intelligenz — schneller,günstiger,wirkungsvoller.','services.seo.title':'SEO und Werbung','services.seo.desc':'Sichtbarkeit bei Google und bezahlte Kampagnen(Google Ads,Meta Ads)— messbar,skalierbar und rentabel ab dem ersten Klick.','services.strategy.title':'Strategie und Branding','services.strategy.desc':'Eine Marke,die Kunden erkennen und im Kopf bleibt — von der Strategie über das visuelle Erscheinungsbild bis zur konsequenten Umsetzung.','about.eyebrow':'Über mich','about.title':'Pole in Deutschland — Digitalmarketing ist meine Leidenschaft und meine Ausbildung','about.p1':'Seit über 10 Jahren lebe ich in Deutschland und verbinde polnische Vielseitigkeit mit deutscher Präzision in der Kundenarbeit. Meine berufliche Erfahrung sammelte ich an der Wyższa Szkoła Menedżerska(Hochschule für Management)in Warschau und erweitere meine Kompetenzen laufend durch Weiterbildungen — u. a. beim DCI in Berlin.','about.p2':'Neben Marketingstrategie und Webentwicklung realisiere ich selbst zahlreiche Projekte — u. a. KI-Influencerinnen,Werbekampagnen sowie Foto- und Videoaufnahmen mit DJI-Drohnen — ich besitze die Betreiberlizenz A1/A3,sodass Ihre Videoinhalte vollständig legal und professionell entstehen.','about.li1':'Über 10 Jahre Lebens- und Berufserfahrung in Deutschland','about.li2':'Ausbildung:Wyższa Szkoła Menedżerska in Warschau','about.li3':'Regelmäßige Weiterbildungen','about.li4':'Lizenzierter DJI-Drohnenpilot(A1/A3)','stats.years':'Jahre Erfahrung in DE','stats.license':'Drohnenpiloten-Lizenz','stats.lang':'Sprachen im Kundenservice','stats.service':'Marketing von A bis Z','portfolio.eyebrow':'Referenzen','portfolio.title':'Aus der Vogelperspektive und mehr','portfolio.sub':'Ausgewählte Arbeiten. Vollständiges Portfolio und Case Studies auf Anfrage.','portfolio.showreel':'Werbung erstellt von Digital Power','portfolio.ai':'KI im Einsatz','portfolio.aiInfluencer':'camila.nomadfit — unsere KI-Influencerin','portfolio.storyboard':'Werbung für ein Bauunternehmen','process.eyebrow':'So arbeiten wir','process.title':'Von der Strategie bis zur Umsetzung — Schritt für Schritt','process.s1.title':'Analyse und Strategie','process.s1.desc':'Wir lernen Ihr Unternehmen,Ihre Ziele und den Wettbewerb kennen — damit keine Maßnahme dem Zufall überlassen wird.','process.s2.title':'Design und Produktion','process.s2.desc':'Wir erstellen Website,Inhalte,Fotos und Drohnenvideos sowie KI-gestützte Kreationen — abgestimmt auf Ihre Marke.','process.s3.title':'Umsetzung','process.s3.desc':'Wir veröffentlichen und konfigurieren Kampagnen und Social Media gemäß dem vereinbarten Plan — ohne Überraschungen.','process.s4.title':'Wachstum und Optimierung','process.s4.desc':'Wir analysieren die Ergebnisse und verbessern kontinuierlich die Wirksamkeit Ihres Online-Marketings — ein gutes Ergebnis ist erst der Anfang.','process.trust':'Wir handeln DSGVO-konform und nach anerkannten Datensicherheitsstandards — Ihre Daten verwenden wir ausschließlich zur Bearbeitung Ihrer Anfrage und geben sie nicht zu Marketingzwecken an Dritte weiter. Details in unserer <a href="datenschutz.html">Datenschutzerklärung</a>.','ctaBanner.title':'Bereit,dass Ihr Unternehmen online durchstartet?','ctaBanner.sub':'Schreiben Sie mir — wir besprechen kostenlos Umfang und Angebot Ihres Projekts.','ctaBanner.btn':'Kontakt aufnehmen','contact.eyebrow':'Kontakt','contact.title':'Lassen Sie uns über Ihr Projekt sprechen','contact.sub':'Ich antworte auf Polnisch,Deutsch und Englisch. Schreiben Sie eine E-Mail oder füllen Sie das Formular aus.','contact.location':'Goslarstraße 5,44359 Dortmund','contact.languages':'Polnisch · Deutsch · Englisch','contact.form.name':'Name','contact.form.email':'E-Mail-Adresse','contact.form.subject':'Worum geht es in Ihrer Anfrage?','contact.form.opt1':'Website','contact.form.opt2':'Social Media','contact.form.opt3':'Drohnenfoto / -video','contact.form.opt4':'Werbung und SEO','contact.form.opt5':'Sonstiges','contact.form.message':'Nachricht','contact.form.send':'Anfrage senden','footer.tagline':'Digitale Kraft für Ihr Unternehmen.','footer.legal':'<a href="datenschutz.html">Datenschutzerklärung</a> · <a href="impressum.html">Impressum</a>',},en:{'brand.logo':'<strong>Digital.</strong>Power','nav.services':'Services','nav.about':'About','nav.portfolio':'Portfolio','nav.contact':'Contact','nav.cta':'Contact','hero.eyebrow':'Digital Marketing · Poland - Germany','hero.headline':'From strategy<br>to execution.','hero.sub':'Social media,websites,SEO and advertising — everything you need to get your business online and growing.','hero.tagline':'Digital power for your business.','hero.ctaPrimary':'Free quote','hero.ctaSecondary':'See services','hero.badgeDrone':'Drone licence A1/A3 · DJI','hero.badgeBilingual':'Polish · German · English','hero.badgeAI':'AI-powered ads','trust.line':'Strategy · Design · Drone · SEO · Social Media — all under one roof.','services.eyebrow':'What we do','services.title':'Services that drive your brand forward','services.sub':'Full-service digital marketing — from the first strategy draft to a finished campaign.','services.web.title':'Websites','services.web.desc':'Modern,fast and responsive websites that sell — built for conversion and SEO.','services.social.title':'Social media management','services.social.desc':'Strategy,content and community management for Instagram,Facebook,TikTok and LinkedIn — more than likes:real reach and customers.','services.drone.title':'Drone photos and videos','services.drone.desc':'Professional DJI drone footage(A1/A3 licence)— real estate,events,advertising,product video.','services.ai.title':'AI-powered advertising','services.ai.desc':'Ad creatives generated and enhanced with artificial intelligence — faster,cheaper,more effective.','services.seo.title':'SEO and advertising','services.seo.desc':'Visibility on Google and paid campaigns(Google Ads,Meta Ads)— measurable,scalable and profitable from the first click.','services.strategy.title':'Strategy and branding','services.strategy.desc':'A brand your customers recognise and remember — from strategy,through visual identity,to consistent execution.','about.eyebrow':'About me','about.title':'A Pole in Germany — digital marketing is my passion and my profession','about.p1':"I've lived in Germany for over 10 years,combining Polish versatility with German precision in client work. I gained my professional experience at the Warsaw School of Management(Wyższa Szkoła Menedżerska),and I keep developing my skills through ongoing training — most recently at DCI in Berlin.",'about.p2':'Besides marketing strategy and website development,I personally run many projects — including an AI influencer,ad campaigns,and DJI drone photo and video shoots. I hold an A1/A3 operator licence,so your video content is always produced fully legally and professionally.','about.li1':'Over 10 years of life and professional experience in Germany','about.li2':'Education:Warsaw School of Management(Wyższa Szkoła Menedżerska)','about.li3':'Regular professional training','about.li4':'Licensed DJI drone operator(A1/A3)','stats.years':'years of experience in Germany','stats.license':'drone pilot licence','stats.lang':'client service languages','stats.service':'end-to-end marketing','portfolio.eyebrow':'Work','portfolio.title':'From a bird\'s-eye view and beyond','portfolio.sub':'Selected material. Full portfolio and case studies on request.','portfolio.showreel':'Advert made by Digital Power','portfolio.ai':'AI in action','portfolio.aiInfluencer':'camila.nomadfit — our AI influencer','portfolio.storyboard':'Advert for a construction company','process.eyebrow':'How we work','process.title':'From strategy to execution — step by step','process.s1.title':'Analysis and strategy','process.s1.desc':'We get to know your business,goals and competitors — so nothing is left to chance.','process.s2.title':'Design and production','process.s2.desc':'We create the website,content,drone photos and videos,and AI-assisted creatives — tailored to your brand.','process.s3.title':'Launch','process.s3.desc':'We publish and set up campaigns and social media according to the agreed plan — no surprises.','process.s4.title':'Growth and optimisation','process.s4.desc':'We analyse results and keep improving the effectiveness of your online marketing — a good result is only the beginning.','process.trust':'We operate in compliance with GDPR and data security standards — we use your data solely to handle your enquiry and never share it with third parties for marketing purposes. Details in our <a href="privacy-policy.html">Privacy Policy</a>.','ctaBanner.title':'Ready to get your business online?','ctaBanner.sub':'Get in touch — we\'ll discuss the scope and quote for your project,free of charge.','ctaBanner.btn':'Get in touch','contact.eyebrow':'Contact','contact.title':"Let's talk about your project",'contact.sub':'I reply in Polish,German and English. Send an email or fill in the form.','contact.location':'Goslarstraße 5,44359 Dortmund','contact.languages':'Polish · German · English','contact.form.name':'Full name','contact.form.email':'Email address','contact.form.subject':'What is your enquiry about?','contact.form.opt1':'Website','contact.form.opt2':'Social media','contact.form.opt3':'Drone photo / video','contact.form.opt4':'Advertising and SEO','contact.form.opt5':'Other','contact.form.message':'Message','contact.form.send':'Send enquiry','footer.tagline':'Digital power for your business.','footer.legal':'<a href="privacy-policy.html">Privacy Policy</a> · <a href="legal-notice.html">Legal Notice</a>',}};const langButtons = document.querySelectorAll('.lang-btn');function applyLang(lang){const strings = dict[lang];document.querySelectorAll('[data-i18n]').forEach(el =>{const key = el.getAttribute('data-i18n');if(strings[key] !== undefined)el.innerHTML = strings[key]});document.querySelectorAll('[data-i18n-placeholder]').forEach(el =>{const key = el.getAttribute('data-i18n-placeholder');if(strings[key] !== undefined)el.placeholder = strings[key]});document.documentElement.lang = lang;langButtons.forEach(b => b.classList.toggle('active',b.dataset.lang === lang));localStorage.setItem('dp-lang',lang)}langButtons.forEach(btn =>{btn.addEventListener('click',()=> applyLang(btn.dataset.lang))});const saved = localStorage.getItem('dp-lang');function detectBrowserLang(){const l =(navigator.language || 'pl').toLowerCase();if(l.startsWith('de'))return 'de';if(l.startsWith('pl'))return 'pl';if(l.startsWith('en'))return 'en';return 'pl'}applyLang(saved || detectBrowserLang());